import React, { useState, useEffect } from "react";
import "./Seo_shortform.css";
import { useLocation, useNavigate } from "react-router-dom";

function Seo_shortform({ videoThumbnail }) {
  const location = useLocation();
  const navigate = useNavigate();
  const { message, results, selectedFeatures, selectedClip } = location.state || {};
  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");
  console.log(results)
  const getVideoUrl = (clipData, fileName) => {
    // If only SEO is selected, prioritize the original clip URL
    if (selectedFeatures.length === 1 && selectedFeatures.includes('SEO')) {
      return selectedClip;
    }

    // Existing logic for other feature combinations
    if (results?.audio_processing?.processed_file_path) {
      const enhancedAudioFileName = results.audio_processing.processed_file_path.split('\\').pop();
      return `http://127.0.0.1:8000/media/processed/${enhancedAudioFileName}`;
    }

    if (results?.video_upscaling?.processed_file_path) {
      const enhancedVideoFileName = results.video_upscaling.processed_file_path.split('\\').pop();
      return `http://127.0.0.1:8000/media/processed/${enhancedVideoFileName}`;
    }

    return `http://127.0.0.1:8000/media/processed/${fileName}`;
  };

  const shouldShowComparison = (features) => {
    return features?.includes('Noise Reduction') || features?.includes('Video Quality');
  };

  const handleCompare = () => {
    const { results, selectedFeatures, selectedClip } = location.state;
    const localPath = selectedClip.replace(
      'http://127.0.0.1:8000/media/processed/',
      'C:\\Users\\aqiba\\Desktop\\test3-main\\test3-main\\backend\\media\\processed\\'
    );
    const clipData = Object.values(results)[0] || {};
    let processedResult = {};

    if (selectedFeatures.includes('Noise Reduction') && clipData.audio_processing) {
      processedResult = {
        audio_processing: clipData.audio_processing
      };
    } else if (selectedFeatures.includes('Video Quality') && clipData.video_upscaling) {
      processedResult = {
        video_upscaling: clipData.video_upscaling
      };
    }

    navigate('/comparison', {
      state: {
        results: processedResult,
        selectedFeatures,
        videoURL: null,
        localVideoPath: localPath,
        seoData: null
      }
    });
  };

  useEffect(() => {
    console.log("Received results:", selectedClip);
  }, [results]);

  return (
    <div className="seo-app">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
          <button className="home-button" onClick={() => navigate('/clipper')}>
            Home
          </button>
        </nav>
      </header>

      <main className="main-content">
        <button className="clipper-btn" onClick={() => navigate('/clipper')}>
          Go to Clipper
        </button>

        {Object.entries(results || {}).map(([fileName, clipData], index) => {
          const videoUrl = getVideoUrl(clipData, fileName);
          const seoData = results?.seo || {};
          const keywords = seoData.keywords?.length ? seoData.keywords.join(", ") : "No keywords available.";
          const description = seoData.description || "No description available.";
          const title = seoData.title || "No title available.";
          const tags = seoData.tags?.length ? seoData.tags.join(", ") : "No tags available.";

          return (
            <div key={index} className="clip-section">
              <div className="media-preview">
                <video className="preview-video" controls>
                  <source src={videoUrl} type="video/mp4" />
                  Your browser does not support the video tag.
                </video>
              </div>

              <div className="customize-clip">
                <div className="seo-data">
                  <div className="seo-box">
                    <h2>Title</h2>
                    <p>{title}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Description</h2>
                    <p>{description}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Keywords</h2>
                    <p>{keywords}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Tags</h2>
                    <p>{tags}</p>
                  </div>
                </div>
                {shouldShowComparison(selectedFeatures) && (
                  <button
                    className="comparison-btn"
                    onClick={() => handleCompare(clipData, fileName)}
                  >
                    Compare Results
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </main>
    </div>
  );
}

export default Seo_shortform;
